#pragma once
#include <JuceHeader.h>

namespace j3logo
{
inline juce::Image loadOfficialLogo()
{
    static const char* data = R"J3LOGO()J3LOGO";
    juce::MemoryBlock block;
    if (!block.fromBase64Encoding(data))
        return {};
    return juce::ImageFileFormat::loadFrom(block.getData(), block.getSize());
}
}
